import {atasForProduct,validateLinks} from './ata-logic.js';
import {Store} from './store.js';
import {remaining} from './request-logic.js';
import {normalize,toast} from './utils.js';
const keys={code:['codigo','codigo do produto','cod','code'],product:['produto','descricao','descricao do produto','material','product'],unit:['unidade','unidade de medida','und','um','unit']};
export const FileIO={async read(files){if(!window.XLSX)throw Error('Processador de planilhas indisponível. Recarregue a página.');const products=[],sources=[];let skipped=0;for(const file of files){if(!/\.(xlsx|xls|csv)$/i.test(file.name))throw Error('Use arquivos XLS, XLSX ou CSV.');if(file.size>8*1024*1024)throw Error('Cada arquivo deve ter até 8 MB.');const bytes=await file.arrayBuffer();let source=bytes;if(/\.csv$/i.test(file.name)){let text=new TextDecoder('utf-8').decode(bytes);if(text.includes('�'))text=new TextDecoder('windows-1252').decode(bytes);source=text}const workbook=XLSX.read(source,{type:typeof source==='string'?'string':'array',cellStyles:true,cellNF:true,cellDates:false});for(const sheetName of workbook.SheetNames){const sheet=workbook.Sheets[sheetName],rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});const headerIndex=rows.findIndex(row=>row.some(x=>keys.product.includes(normalize(x).trim())));if(headerIndex<0){skipped++;continue}const header=rows[headerIndex].map(x=>normalize(x).trim());const map=Object.fromEntries(Object.entries(keys).map(([key,aliases])=>[key,header.findIndex(x=>aliases.includes(x))]));if(map.code<0||map.unit<0)throw Error(`A aba “${sheetName}” precisa das colunas Código, Produto e Unidade de Medida.`);for(const row of rows.slice(headerIndex+1)){if(!String(row[map.product]??'').trim())continue;const p={};for(const k of Object.keys(keys))p[k]=String(row[map[k]]??'').trim();if(!p.code||!p.unit){skipped++;continue}products.push({...p,id:crypto.randomUUID()})}}sources.push({name:file.name,workbook})}if(!products.length)throw Error('Nenhum produto válido. Use as colunas Código, Produto e Unidade de Medida.');return {products,sources,skipped}},commit(result,mode,ataId){const ata=Store.data.atas.find(a=>a.id===ataId);if(ataId&&!ata)throw Error('ATA de destino não encontrada.');if(!['merge','replace'].includes(mode))throw Error('Modo de importação inválido.');if(!ata&&mode==='replace')throw Error('Para importar no catálogo sem ATA, use Adicionar / mesclar produtos.');const catalog=[...Store.data.products],importedIds=[];let updated=0;for(const p of result.products){const index=catalog.findIndex(x=>normalize(x.code)===normalize(p.code));if(index>=0){catalog[index]={...p,id:catalog[index].id};updated++;importedIds.push(catalog[index].id)}else{catalog.push(p);importedIds.push(p.id)}}const links=ata?[...new Set(mode==='replace'?importedIds:[...(ata.productIds||[]),...importedIds])]:[];if(ata)validateLinks(Store.data,ata.id,ata.sectorIds||[],links);Store.data.products=catalog;if(ata)ata.productIds=links;Store.data.sources=[...(Store.data.sources||[]),...result.sources.map(s=>({...s,ataId}))];const saved=Store.save();toast(saved?`${importedIds.length} produto(s) ${ata?`vinculado(s) à ${ata.number}`:'importado(s) no catálogo'}. ${updated} códigos mesclados.`:'Importado nesta sessão. Armazenamento cheio: exporte para guardar os dados.');},export(type,rows){if(!window.XLSX)return toast('Processador de planilhas indisponível.');const map={requests:{requestNumber:'Solicitação',responsible:'Responsável',ramal:'Ramal',received:'Recebido',remaining:'Pendente',code:'Código',product:'Produto',unit:'Unidade de Medida',quantity:'Quantidade',sector:'Setor',status:'Status',date:'Data',ata:'ATA'},products:{code:'Código',product:'Produto',unit:'Unidade de Medida',ataNames:'ATAs vinculadas'},sectors:{name:'Setor',responsible:'Responsável',contact:'Contato'},atas:{number:'ATA',supplier:'Fornecedor',validity:'Validade',description:'Descrição',sectorNames:'Setores participantes',productNames:'Produtos vinculados'}}[type];const output=rows.map(row=>Object.fromEntries(Object.entries(map).map(([k,label])=>[label,k==='remaining'?(row.status==='Cancelada'?0:remaining(row)):k==='ataNames'?atasForProduct(Store.data,row.id).map(a=>a.number).join(', '):k==='sectorNames'?Store.data.sectors.filter(s=>row.sectorIds?.includes(s.id)).map(s=>s.name).join(', '):k==='productNames'?Store.data.products.filter(p=>row.productIds?.includes(p.id)).map(p=>p.product).join(', '):row[k]??''])));const wb=XLSX.utils.book_new();const ws=XLSX.utils.json_to_sheet(output.length?output:[Object.fromEntries(Object.values(map).map(v=>[v,'']))]);ws['!cols']=Object.keys(map).map(k=>({wch:k==='product'||k==='description'?38:22}));for(const key of Object.keys(ws)){if(key.startsWith('!'))continue;const cell=ws[key];const header=XLSX.utils.decode_cell(key).r===0;cell.s={font:{name:'Calibri',sz:11,...(header?{bold:true,color:{rgb:'FFFFFF'}}:{})},fill:{fgColor:{rgb:header?'7255D5':XLSX.utils.decode_cell(key).r%2?'F5F2FC':'FFFFFF'}},alignment:{vertical:'center'},border:{bottom:{style:'thin',color:{rgb:'EAE6F2'}}}}}XLSX.utils.book_append_sheet(wb,ws,'Relatório');let n=1;for(const source of Store.data.sources||[]){for(const name of source.workbook.SheetNames){if(n>100)break;XLSX.utils.book_append_sheet(wb,structuredClone(source.workbook.Sheets[name]),`Origem ${n++} - ${name}`.slice(0,31))}}XLSX.writeFile(wb,`supri-${type}-${new Date().toISOString().slice(0,10)}.xlsx`);toast('Planilha exportada com relatório e abas de origem.');},template(){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['Código','Produto','Unidade de Medida'],['MAT-001','Papel A4 branco 75g/m²','Resma']]),'Produtos');XLSX.writeFile(wb,'modelo-produtos-supri.xlsx')}};
